cd /home/ian/hellow-world2; python3 -m http.server 8765 >/tmp/hw-srv.log 2>&1 & echo $! > /tmp/hw.pid; sleep 1
PW=$(dirname $(dirname $(readlink -f $(which playwright))))
cat > /tmp/hw-e2e.mjs <<EOF
import { createRequire } from "module";
const require = createRequire("$PW/");
const { chromium } = require("playwright");
const URL = "http://localhost:8765/";
const b = await chromium.launch();
const errs = [];
const ctx = await b.newContext({ viewport: { width: 1440, height: 900 }, permissions: ["clipboard-read","clipboard-write"] });
const p = await ctx.newPage();
p.on("console", m => m.type()==="error" && errs.push(m.text()));
p.on("pageerror", e => errs.push("PAGEERR " + e.message));
p.on("requestfailed", r => errs.push("REQFAIL " + r.url()));
p.on("response", r => r.status() >= 400 && errs.push("HTTP " + r.status() + " " + r.url()));
const h = p.locator("#headline");
const txt = () => h.evaluate(e => e.textContent);
await p.goto(URL); console.log("1", await txt());
await p.screenshot({ path: "/tmp/hw-desktop.png" });
await h.click(); await p.keyboard.press("Control+A"); await p.keyboard.type("hi pi");
console.log("2", await p.evaluate(() => localStorage["hello-world:text"]));
await p.screenshot({ path: "/tmp/hw-focus.png" });
await p.reload(); console.log("3", await txt());
await h.click(); await p.keyboard.press("End"); await p.keyboard.press("Enter");
console.log("4", await txt(), await h.evaluate(e => e.childElementCount), await p.evaluate(() => document.activeElement.id));
await h.click(); await p.keyboard.press("End");
await p.evaluate(() => { const dt = new DataTransfer(); dt.setData("text/html","<b>x</b>"); dt.setData("text/plain","<b>x</b>");
  document.getElementById("headline").dispatchEvent(new ClipboardEvent("paste",{clipboardData:dt,bubbles:true,cancelable:true})); });
console.log("5", await txt(), await h.evaluate(e => e.childElementCount), await p.evaluate(() => localStorage["hello-world:text"]));
await h.click(); await p.keyboard.press("Control+A"); await p.keyboard.press("Backspace");
await p.evaluate(() => document.activeElement.blur());
console.log("6", await txt(), await p.evaluate(() => localStorage.getItem("hello-world:text")));
await p.reload(); console.log("6b", await txt());
console.log("8 errors:", JSON.stringify(errs));
// AC6
const c2 = await b.newContext(); const p2 = await c2.newPage(); const e2 = [];
p2.on("console", m => m.type()==="error" && e2.push(m.text())); p2.on("pageerror", e => e2.push("PAGEERR "+e.message));
await c2.addInitScript(() => { Object.defineProperty(window, "localStorage", { get() { throw new Error("blocked"); } }); });
await p2.goto(URL); const h2 = p2.locator("#headline");
await h2.click(); await p2.keyboard.press("Control+A"); await p2.keyboard.type("still works");
console.log("7", await h2.evaluate(e=>e.textContent), JSON.stringify(e2));
const c3 = await b.newContext(); const p3 = await c3.newPage(); const e3=[];
p3.on("console", m => m.type()==="error" && e3.push(m.text()));
await c3.addInitScript(() => { Storage.prototype.setItem = () => { throw new Error("quota"); }; });
await p3.goto(URL); await p3.locator("#headline").click(); await p3.keyboard.type("!");
console.log("7b", JSON.stringify(e3));
const c4 = await b.newContext({ viewport: { width: 360, height: 740 }, reducedMotion: "reduce" });
const p4 = await c4.newPage(); await p4.goto(URL); await p4.screenshot({ path: "/tmp/hw-mobile.png" });
console.log("rm anim", await p4.locator(".blob--1").evaluate(e => getComputedStyle(e).animationName), "overflow", await p4.evaluate(() => document.documentElement.scrollWidth));
await b.close();
EOF
node /tmp/hw-e2e.mjs; kill $(cat /tmp/hw.pid)

